 static string dir; static int count; static List<string> log=new List<string>();
 static object Call(Type t,string name,object target,params object[] args){try{return t.GetMethod(name,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Static|BindingFlags.Instance).Invoke(target,args);}catch(TargetInvocationException e){throw e.InnerException;}}
 static void Eq(decimal got,decimal want,string why){if(got!=want)throw new Exception(why+": expected "+want+", got "+got);count++;}
 static decimal N(ExcelWorksheet w,int r,int c){return Convert.ToDecimal(w.Cells[r,c].Value??0);}
 static string Make(string name,string[] headers,params object[][] rows){string path=Path.Combine(dir,name+".xlsx");using(var p=new ExcelPackage()){var w=p.Workbook.Worksheets.Add("자료");for(int c=0;c<headers.Length;c++)w.Cells[1,c+1].Value=headers[c];for(int r=0;r<rows.Length;r++)for(int c=0;c<rows[r].Length;c++)w.Cells[r+2,c+1].Value=rows[r][c];p.SaveAs(new FileInfo(path));}return path;}
 static Dictionary<string,Charge> Parse(string path,string ins){var d=new Dictionary<string,Charge>();var logs=new List<Recognition>();Call(typeof(Processor),"ReadCharges",null,path,ins,ins,d,logs);if(d.Count==0)throw new Exception("parse failed "+String.Join(";",logs.Select(x=>x.Detail)));return d;}
 static List<ResultRow> Compare(Dictionary<string,Charge> c,Dictionary<string,Person> p=null){return (List<ResultRow>)Call(typeof(Processor),"Compare",null,p??new Dictionary<string,Person>(),c);}
