  var current=Make("current",new[]{"성명","주민등록번호","사업장관리번호","당월분본인기여금","당월분사용자부담금","정산본인기여금원","정산사용자부담금원"},new object[]{"가상정산","900101","11111111111",100000,100000,-20000,-20000});Eq(Parse(current,"국민연금").Values.Single().CompareAmount,80000,"current-only pension normalized");log.Add("PASS pension total/current headers, positive/refund/net-zero, payroll settlement");
