  string wr=Result("base-worker",new InputSet{HealthOther=wageHealth,Pension=wagePension});Assign(wr,"교특회계");WorkerCheck(wr,new decimal[]{70900,9340,76000,0,0},new decimal[]{-1000,-100,-19000,0,0});log.Add("PASS worker wage-base formulas preserved; pension 2000000 * template rate -19000 = 76000, not notice total 81000");

