  string reordered=Make("reordered",new[]{"성명","주민등록번호","사업장관리번호","정산보험료본인기여금원","정산보험료사용자부담금원","총부담금계본인기여금원","총부담금계사용자부담금원"},new object[]{"가상정산","900101","11111111111",-20000,-19000,80000,81000});var rc=Parse(reordered,"국민연금").Values.Single();Eq(rc.CompareAmount,80000,"settlement column preceding total personal");Eq(rc.EmployerAmount,81000,"settlement column preceding total employer");
