 static void JobEdit(string source){
  string path=Path.Combine(dir,"job-edit.xlsm");File.Copy(source,path,true);
  using(var f=new MainForm()){
   Call(typeof(MainForm),"LoadResultIntoUi",f,path);
   Func<IndividualRowData> get=()=>((IndividualDashboardModel)typeof(MainForm).GetField("individualDashboard",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f)).Rows.Single();
   var row=get();string key=(string)Call(typeof(MainForm),"StablePersonKey",null,row),fund=row.Fund;
   var checkedKeys=(HashSet<string>)typeof(MainForm).GetField("reviewCheckedKeys",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f);checkedKeys.Add(key);Call(typeof(MainForm),"PersistReviewChangesCore",f,path);Call(typeof(MainForm),"LoadResultIntoUi",f,path);row=get();
   var before=(decimal[])Call(typeof(MainForm),"ManualValues202",null,row);
   foreach(string job in new[]{"조리실무사","교육실무사","","  교육실무사  "}){
    row=get();using(var bubble=new ReviewEditBubble202(row,"직종명 수정 검증",true,null,(values,newJob)=>Call(typeof(MainForm),"SaveManual202",f,path,key,values,newJob))){bubble.Show();Application.DoEvents();((TextBox)bubble.Controls.Find("JobNameInput",true).Single()).Text=job;
     if(job=="조리실무사")using(var bmp=new System.Drawing.Bitmap(bubble.Width,bubble.Height)){bubble.DrawToBitmap(bmp,new System.Drawing.Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save(Path.Combine(dir,"job-editor.png"));}
     ((Button)bubble.Controls.Find("SaveCorrection",true).Single()).PerformClick();if(!bubble.IsDisposed)throw new Exception("job save did not close popup");
    }
    row=get();if(row.Job!=job.Trim())throw new Exception("job save/reload failed");count++;
    if(row.Fund!=fund||!(bool)Call(typeof(MainForm),"IsReviewCompleted",f,row))throw new Exception("job-only changed fund or completed state");count++;
    if(!before.SequenceEqual((decimal[])Call(typeof(MainForm),"ManualValues202",null,row)))throw new Exception("job-only changed amounts");count++;
   }
   byte[] saved=File.ReadAllBytes(path);using(var bubble=new ReviewEditBubble202(get(),"취소 검증",true,null,(v,j)=>Call(typeof(MainForm),"SaveManual202",f,path,key,v,j))){bubble.Show();Application.DoEvents();((TextBox)bubble.Controls.Find("JobNameInput",true).Single()).Text="저장하지않음";bubble.Close();}if(!saved.SequenceEqual(File.ReadAllBytes(path)))throw new Exception("cancel changed file");count++;
   Call(typeof(MainForm),"PersistReviewChangesCore",f,path);Call(typeof(MainForm),"LoadResultIntoUi",f,path);if(get().Job!="교육실무사")throw new Exception("general save lost job");count++;
  }
  using(var p=new ExcelPackage(new FileInfo(path)))using(var original=new ExcelPackage(new FileInfo(source))){if(!p.Workbook.Worksheets["수기보정이력"].Cells.Any(c=>c.Text=="직종명"))throw new Exception("job audit missing");count++;foreach(var w in original.Workbook.Worksheets.Where(w=>w.Name.StartsWith("원본")))if(w.WorksheetXml.OuterXml!=p.Workbook.Worksheets[w.Name].WorksheetXml.OuterXml)throw new Exception("job save changed original");}
  string output=SubmissionGenerator.Create(path,dir,false,new SubmissionInfo{InstitutionName="직종반영검증"});using(var p=new ExcelPackage(new FileInfo(output))){if(p.Workbook.Worksheets[1].Cells[7,5].Text!="교육실무사")throw new Exception("submission job missing");count++;}
  log.Add("PASS job editor: blank/replacement/clear/trim, save/reopen/general save, cancel, amounts/fund/completed-state preservation, audit, originals, actual submission E7");
 }
 static Person Payroll(string path){var people=new Dictionary<string,Person>();var logs=new List<Recognition>();Call(typeof(Processor),"ReadPayroll",null,path,"교육공무직","교특",people,logs);if(people.Count!=1)throw new Exception("payroll parse count");return people.Values.Single();}
 static void PayrollSettlements(){
  string[] headers={"성명","주민등록번호","건강보험 복직정산","건강보험","건강보험 휴직정산","건강보험 연말정산","건강보험 퇴직정산","건강보험 기타정산","노인장기요양보험","장기요양 복직정산","장기요양 휴직정산","장기요양 연말정산","국민연금","국민연금 복직정산","국민연금 소급","고용보험","고용보험 퇴직정산","고용보험 연말정산","고용보험 복직정산","산재보험","산재보험 퇴직정산","산재보험 연말정산","산재보험 휴직정산","건강보험 기관부담 정산","건강보험 정산사유","건강보험 정산기간"};
  var row=new object[]{"가상정산","900101",-2000,100000,-1000,500,300,200,13000,-260,-130,65,95000,-3000,1000,10000,-100,200,-300,5000,-50,100,-150,999999,"휴직",202609};
  var x=Payroll(Make("payroll-all",headers,row));Eq(x.HealthCurrent,100000,"current excludes earlier settlement column");Eq(x.HealthSettlementHealth,-2000,"all health settlement types");Eq(x.LongTermSettlement,-325,"all long-term types");Eq(x.Health,110675,"health total settlement once");Eq(x.PensionSettlement,-2000,"pension settlement and retro");Eq(x.Pension,93000,"pension payroll total");Eq(x.EmploymentSettlement,-200,"employment all three settlements once");Eq(x.IndustrialSettlement,-100,"industrial all three settlements once");
  var h=Parse(Health("payroll-match-health",100000,13000,-2000,-325),"건강보험");var matched=Compare(h,new Dictionary<string,Person>{{x.Key,x}});Eq(matched.First(v=>v.Insurance=="건강보험").Difference,0,"parsed payroll -> comparison health");using(var p=Ui(matched))Eq(N(p.Workbook.Worksheets[1],2,9),0,"parsed payroll -> UI health difference");
  var rev=Payroll(Make("payroll-reversed",headers.Reverse().ToArray(),row.Reverse().ToArray()));Eq(rev.Health,x.Health,"column order independent");Eq(rev.Employment,x.Employment,"order independent employment");
  var total=Payroll(Make("payroll-total",headers.Concat(new[]{"건강보험 정산합계"}).ToArray(),row.Concat(new object[]{-2000}).ToArray()));Eq(total.HealthSettlementHealth,-2000,"aggregate not added to details");
  var zero=Payroll(Make("payroll-zero-total",headers.Concat(new[]{"건강보험 정산합계"}).ToArray(),row.Concat(new object[]{0}).ToArray()));Eq(zero.HealthSettlementHealth,0,"zero settlement total authoritative");
  var blank=Payroll(Make("payroll-blank-total",headers.Concat(new[]{"건강보험 정산합계"}).ToArray(),row.Concat(new object[]{null}).ToArray()));Eq(blank.HealthSettlementHealth,-2000,"blank total uses detailed settlements");
  var other=Payroll(Make("payroll-other",new[]{"성명","주민등록번호","건강보험","건강보험 기타정산합계","건강보험 기타정산1","건강보험 기타정산2","건강보험 연말정산"},new object[]{"가상급여","900101",100000,300,100,200,-50}));Eq(other.HealthSettlementHealth,250,"category subtotal excludes its details");
  var careTotal=Payroll(Make("payroll-care-total",headers.Concat(new[]{"장기요양 정산합계"}).ToArray(),row.Concat(new object[]{-325}).ToArray()));Eq(careTotal.LongTermSettlement,-325,"care aggregate without insurance suffix");
  var unknown=Payroll(Make("payroll-new-settlement",headers.Concat(new[]{"건강보험 특별정산","고용보험 복직자정산"}).ToArray(),row.Concat(new object[]{-777,88}).ToArray()));Eq(unknown.HealthSettlementHealth,-2777,"unlisted health settlement kind");Eq(unknown.EmploymentSettlement,-112,"unlisted employment settlement kind");
  log.Add("PASS payroll insurance-name matching: leave/return/year-end/termination/other, signed values, order, totals and no double counting");
 }
 static void PensionFormat(string fixture){
  var expected=new List<decimal>();string copy=Path.Combine(dir,"new-pension-format.xlsx");
  using(var p=new ExcelPackage(new FileInfo(fixture))){var w=p.Workbook.Worksheets[1];for(int r=4;r<=w.Dimension.End.Row;r++){w.Cells[r,3].Value="가상연금"+(r-3);w.Cells[r,4].Value="900101";expected.Add(N(w,r,5));}p.SaveAs(new FileInfo(copy));}
  string result=Result("new-pension-format",new InputSet{Pension=copy});Assign(result,"교특회계");
  string output=SubmissionGenerator.Create(result,dir,false,new SubmissionInfo{InstitutionName="신양식검증"});
  using(var p=new ExcelPackage(new FileInfo(output))){var w=p.Workbook.Worksheets[1];for(int r=7;r<7+expected.Count;r++){int index=Int32.Parse(w.Cells[r,6].Text.Replace("가상연금",""))-1;Eq(N(w,r,11),expected[index],"new pension current base row "+index);if(String.IsNullOrWhiteSpace(w.Cells[r,22].Formula)||String.IsNullOrWhiteSpace(w.Cells[r,24].Formula))throw new Exception("pension template formulas lost");count++;} }
  log.Add("PASS supplied pension layout "+expected.Count+" rows: E current wage -> submission K; formulas preserved");
  using(var p=new ExcelPackage(new FileInfo(copy))){var w=p.Workbook.Worksheets[1];w.Cells[4,11].Value=9999999;w.Cells[4,14].Value=-1234;w.Cells[4,15].Value=-1234;w.Cells[5,5].Value=0;w.Cells[5,11].Value=8888888;p.Save();}
  var charges=Parse(copy,"국민연금");var first=charges.Values.Single(x=>x.Name=="가상연금1");Eq(first.EmployerAmount,144586,"current-only pension total plus retro once");Eq(first.SettlementEmployer,-1234,"pension retro employer");
  result=Result("new-pension-retro",new InputSet{Pension=copy});Assign(result,"교특회계");output=SubmissionGenerator.Create(result,dir,false,new SubmissionInfo{InstitutionName="소급분검증"});
  using(var p=new ExcelPackage(new FileInfo(output))){var w=p.Workbook.Worksheets[1];for(int r=7;r<7+expected.Count;r++){if(w.Cells[r,6].Text=="가상연금1"){Eq(N(w,r,11),3070000,"prefer current over nonzero retro wage");Eq(N(w,r,23),-1234,"retro premium reaches settlement W");}if(w.Cells[r,6].Text=="가상연금2")Eq(N(w,r,11),0,"zero current must not fallback to retro wage");}}
  log.Add("PASS nonzero retro wage, zero current wage, current-only totals and separate retro settlement");
 }
